import * as THREE from '../three.module.js';
export class BowlerActionController {
 constructor(bowler){this.bowler=bowler;this.arm='right';this.wicket='over';this.style='semi';}
 prepare(intent){const sign=this.arm==='left'?-1:1;return {...intent,bowlingArm:this.arm,wicketSide:this.wicket,actionStyle:this.style,releaseSide:sign*(this.wicket==='around'?-.82:.32),armSlot:intent.armSlot*sign,wrist:intent.wrist*sign};}
 animate(time,intent){const b=this.bowler,p=Math.min(1,time/intent.runupSeconds),left=intent.bowlingArm==='left',arm=left?2:3,other=left?3:2,sign=left?-1:1,cycle=Math.sin(time*(intent.spin?8:13));b.g.position.set(intent.releaseSide,Math.sin(Math.PI*p)*.025,THREE.MathUtils.lerp(intent.spin?-22.5:-27.5,-18.3,p));b.g.rotation.set(0,0,0);b.limbs[0].rotation.x=cycle*.5;b.limbs[1].rotation.x=-cycle*.5;b.limbs[2].rotation.set(-cycle*.65,0,0);b.limbs[3].rotation.set(cycle*.65,0,0);const a=THREE.MathUtils.clamp((p-.68)/.32,0,1),turn={front:.08,semi:.42,side:.82}[intent.actionStyle]??.42;b.torso.rotation.y=sign*turn*Math.sin(a*Math.PI);if(p>.68){b.limbs[arm].rotation.x=-Math.PI*a;b.limbs[arm].rotation.z=intent.armSlot*a;b.hands[arm-2].rotation.y=intent.wrist*a;b.limbs[other].rotation.x=-Math.PI*.7*(1-a);b.g.rotation.z=sign*Math.sin(a*Math.PI)*.09;b.limbs[0].rotation.x=-.3*(1-a);b.limbs[1].rotation.x=.1;}b.hand=b.hands[arm-2];b.g.updateMatrixWorld(true);}
}
